<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use App\Services\{Access,Files,Audit,Records};
class MutationController {
 private function query(){$q=DB::table('mutasi as m')->join('warga as w','w.id','=','m.warga_id')->join('rt as r','r.id','=','m.rt_id')->whereNull('m.deleted_at')->select('m.*','w.nama','w.nik','r.nomor as rt_nomor');if(!auth()->user()->isAdmin())$q->whereIn('m.rt_id',Access::ids());if(auth()->user()->roleCode()==='WARGA')$q->where('m.pelapor_id',auth()->id());return $q;}
 public function index(Request $r){Access::menu('mutasi');$q=$this->query();if($r->filled('q'))$q->where('w.nama','like','%'.mb_substr($r->string('q'),0,100).'%');if(in_array($r->jenis,['masuk','keluar','lahir','mati']))$q->where('m.jenis',$r->jenis);return view('mutations',['rows'=>$q->orderByDesc('m.id')->paginate(15)->withQueryString()]);}
 public function form(){Access::menu('mutasi','tambah');abort_unless(auth()->user()->isOperator()||auth()->user()->roleCode()==='WARGA',403);$options=Records::options();if(auth()->user()->roleCode()==='WARGA'){$own=Access::warga(auth()->user()->warga_id);$options['warga']=DB::table('warga')->where('kartu_keluarga_id',$own->kartu_keluarga_id)->where('status','aktif')->whereNull('deleted_at')->pluck('nama','id')->all();}return view('mutation-form',compact('options'));}
 public function store(Request $r){Access::menu('mutasi','tambah');abort_unless($r->user()->isOperator()||$r->user()->roleCode()==='WARGA',403);$base=$r->validate(['jenis'=>'required|in:masuk,keluar,lahir,mati','tanggal_peristiwa'=>'required|date|before_or_equal:today','catatan'=>'nullable|string|max:2000']);$jenis=$base['jenis'];
  if(in_array($jenis,['masuk','lahir'])){$rules=['kk_tujuan_id'=>'required|integer|exists:kartu_keluarga,id','nama'=>'required|string|max:150','nik'=>[$jenis==='masuk'?'required':'nullable','digits:16'],'tanggal_lahir'=>($jenis==='lahir'?'nullable':'required').'|date|before_or_equal:today','jenis_kelamin'=>'required|in:L,P','telepon'=>($jenis==='masuk'?'required':'nullable').'|string|max:25','hubungan_keluarga'=>'required|in:kepala_keluarga,istri,suami,anak,lainnya'];if($jenis==='masuk')$rules+=['alamat_asal'=>'required|string|max:2000','status_rumah'=>'required|in:milik,sewa,kontrak','ktp'=>Files::rule(true),'kkfile'=>Files::rule(true)];else $rules+=['nama_ayah'=>'required|string|max:150','nama_ibu'=>'required|string|max:150','surat_lahir'=>Files::rule(true)];$v=$r->validate($rules);$kk=Access::kk((int)$v['kk_tujuan_id']);$hunian=DB::table('hunian')->find($kk->hunian_id);$rtId=$hunian->rt_id;
  }else{$v=$r->validate(['warga_id'=>'required|integer|exists:warga,id']+($jenis==='keluar'?['alamat_tujuan'=>'required|string|max:2000','alasan'=>'required|string|max:2000']:['penyebab'=>'required|in:sakit,usia,lainnya','keterangan'=>'nullable|string|max:2000','surat_mati'=>Files::rule(true)]));$w=Access::warga((int)$v['warga_id'],true);abort_unless($w->status==='aktif',422,'Mutasi hanya dapat diajukan untuk warga aktif.');$rtId=$w->rt_id;}
  DB::transaction(function()use($r,$base,$jenis,$v,$rtId){
   if(in_array($jenis,['masuk','lahir'])){$person=collect($v)->only(['nama','nik','tanggal_lahir','jenis_kelamin','telepon','hubungan_keluarga'])->all();$person['kartu_keluarga_id']=$v['kk_tujuan_id'];$person['nik']=$person['nik']??null;if($jenis==='lahir'){$person['tanggal_lahir']=$base['tanggal_peristiwa'];$person['hubungan_keluarga']='anak';}
    $existing=$person['nik']?DB::table('warga')->where('nik',$person['nik'])->lockForUpdate()->first():null;if($existing){abort_if($existing->deleted_at||$jenis==='lahir'||!in_array($existing->status,['draf','pindah']),422,'NIK sudah tercatat. Hubungi Administrator untuk koreksi atau perpindahan data.');if(!auth()->user()->isAdmin()&&$existing->kartu_keluarga_id)Access::warga($existing->id,true);$w=(object)$existing;}else{$new=DB::table('warga')->insertGetId($person+['status'=>'draf','created_at'=>now(),'updated_at'=>now()]);$w=DB::table('warga')->find($new);}
   }else{$w=DB::table('warga')->where('id',$v['warga_id'])->lockForUpdate()->first();$person=null;}
   abort_if(DB::table('mutasi')->where('warga_id',$w->id)->where('status','draf')->whereNull('deleted_at')->exists(),422,'Warga ini masih memiliki mutasi yang menunggu pencatatan.');
   $mid=DB::table('mutasi')->insertGetId($base+['warga_id'=>$w->id,'rt_id'=>$rtId,'pelapor_id'=>auth()->id(),'kk_tujuan_id'=>$v['kk_tujuan_id']??null,'status'=>'draf','snapshot'=>json_encode(['sebelum'=>$w,'data_baru'=>$person]),'created_at'=>now(),'updated_at'=>now()]);
   match($jenis){
    'masuk'=>DB::table('mutasi_masuk')->insert(['mutasi_id'=>$mid,'alamat_asal'=>$v['alamat_asal'],'status_rumah'=>$v['status_rumah'],'ktp_berkas_id'=>Files::upload($r->file('ktp')),'kk_berkas_id'=>Files::upload($r->file('kkfile'))]),
    'keluar'=>DB::table('mutasi_keluar')->insert(['mutasi_id'=>$mid,'alamat_tujuan'=>$v['alamat_tujuan'],'alasan'=>$v['alasan'],'tanggal_keluar'=>$base['tanggal_peristiwa']]),
    'lahir'=>DB::table('mutasi_lahir')->insert(['mutasi_id'=>$mid,'nama_ayah'=>$v['nama_ayah'],'nama_ibu'=>$v['nama_ibu'],'surat_lahir_berkas_id'=>Files::upload($r->file('surat_lahir'))]),
    'mati'=>DB::table('mutasi_mati')->insert(['mutasi_id'=>$mid,'penyebab'=>$v['penyebab'],'keterangan'=>$v['keterangan']??null,'surat_mati_berkas_id'=>Files::upload($r->file('surat_mati'))])};Audit::record('ajukan_mutasi','mutasi',$mid,null,$base);
  });return redirect('/mutasi')->with('success','Laporan mutasi tersimpan. RT / Administrator dapat memeriksa lalu menerapkan pembaruan data induk.');
 }
 public function show(int $id){Access::menu('mutasi');$m=$this->query()->where('m.id',$id)->first();abort_unless($m,404);$detail=DB::table('mutasi_'.$m->jenis)->where('mutasi_id',$id)->first();$w=DB::table('warga')->find($m->warga_id);$replacement=DB::table('warga')->where('kartu_keluarga_id',$w->kartu_keluarga_id)->where('id','!=',$w->id)->where('status','aktif')->whereNull('deleted_at')->get();return view('mutation-detail',compact('m','detail','w','replacement'));}
 public function apply(Request $r,int $id){Access::menu('mutasi','ubah');abort_unless($r->user()->isOperator(),403);$r->validate(['pengganti_id'=>'nullable|integer|exists:warga,id']);DB::transaction(function()use($id,$r){$m=DB::table('mutasi')->where('id',$id)->whereNull('deleted_at')->lockForUpdate()->first();abort_unless($m,404);Access::rt($m->rt_id);abort_unless($m->status==='draf'&&!$m->diterapkan_pada,422,'Mutasi sudah diproses.');$w=DB::table('warga')->where('id',$m->warga_id)->lockForUpdate()->first();$snap=json_decode($m->snapshot,true);$before=(array)$w;
   if(in_array($m->jenis,['masuk','lahir'])){$k=Access::kk($m->kk_tujuan_id);DB::table('kartu_keluarga')->where('id',$k->id)->lockForUpdate()->first();$data=$snap['data_baru'];abort_unless(in_array($w->status,['draf','pindah']),422,'Status warga sudah berubah; periksa data sebelum menerapkan.');$heads=DB::table('warga')->where('kartu_keluarga_id',$k->id)->where('hubungan_keluarga','kepala_keluarga')->where('status','aktif')->whereNull('deleted_at')->where('id','!=',$w->id)->exists();if($data['hubungan_keluarga']==='kepala_keluarga')abort_if($heads,422,'KK tujuan sudah memiliki kepala keluarga aktif.');else abort_unless($heads,422,'Tetapkan kepala keluarga pada KK tujuan terlebih dahulu.');DB::table('warga')->where('id',$w->id)->update($data+['status'=>'aktif','updated_at'=>now()]);DB::table('kartu_keluarga')->where('id',$k->id)->update(['status'=>'aktif','updated_at'=>now()]);
   }else{abort_unless($w->status==='aktif',422,'Warga sudah tidak aktif.');$remaining=DB::table('warga')->where('kartu_keluarga_id',$w->kartu_keluarga_id)->where('id','!=',$w->id)->where('status','aktif')->whereNull('deleted_at')->get();$head=$w->hubungan_keluarga==='kepala_keluarga'&&$remaining->count();if($head)abort_unless($remaining->contains('id',(int)$r->pengganti_id),422,'Pilih kepala keluarga pengganti dari anggota keluarga aktif.');DB::table('warga')->where('id',$w->id)->update(['status'=>$m->jenis==='keluar'?'pindah':'meninggal','updated_at'=>now()]);if($head)DB::table('warga')->where('id',$r->pengganti_id)->update(['hubungan_keluarga'=>'kepala_keluarga','updated_at'=>now()]);if(!$remaining->count())DB::table('kartu_keluarga')->where('id',$w->kartu_keluarga_id)->update(['status'=>'nonaktif','updated_at'=>now()]);}
   $snap['sebelum_diterapkan']=$before;$snap['sesudah']=DB::table('warga')->find($w->id);DB::table('mutasi')->where('id',$id)->update(['status'=>'tercatat','pencatat_id'=>auth()->id(),'diterapkan_pada'=>now(),'snapshot'=>json_encode($snap),'updated_at'=>now()]);Audit::record('terapkan_mutasi','mutasi',$id,$before,$snap['sesudah']);});return back()->with('success','Mutasi diterapkan satu kali. Data induk dan rekap warga/KK telah diperbarui.');}
 public function update(Request $r,int $id){abort_unless($r->user()->isAdmin(),403);$m=$this->query()->where('m.id',$id)->first();abort_unless($m,404);$v=$r->validate(['catatan'=>'nullable|string|max:2000']);DB::table('mutasi')->where('id',$id)->update($v+['updated_at'=>now()]);Audit::record('ubah_catatan','mutasi',$id,$m,$v);return back()->with('success','Catatan mutasi diperbarui. Koreksi data kependudukan dilakukan pada data induk dan dicatat dalam audit.');}
 public function destroy(int $id){abort_unless(auth()->user()->isAdmin(),403);$m=$this->query()->where('m.id',$id)->first();abort_unless($m,404);DB::transaction(function()use($m){DB::table('mutasi')->where('id',$m->id)->update(['deleted_at'=>now(),'updated_at'=>now()]);Audit::record('hapus_logis','mutasi',$m->id,$m);});return redirect('/mutasi')->with('success','Rekaman mutasi dihapus dari daftar. Riwayat audit dan hasil pembaruan data induk tetap dipertahankan.');}
}
